assets/css/base.css.data:
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 88px; }
body {
  margin: 0; min-height: 100vh; background: var(--bg); color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; }
button:focus-visible, a:focus-visible { outline: 2px solid var(--blue); outline-offset: 4px; }
.skip-link {
  position: fixed; top: 10px; left: 10px; z-index: 100;
  padding: 12px 16px; border: 1px solid var(--blue); border-radius: 10px;
  background: var(--panel); color: var(--text);
  transform: translateY(-160%);
}
.skip-link:focus { transform: translateY(0); }
main { overflow: hidden; }
h1, h2, h3, p { overflow-wrap: anywhere; }
h3 { margin: 0; font-size: 15px; letter-spacing: -.25px; }
h2 { margin: 0; font-size: clamp(27px, 4vw, 38px); line-height: 1.16; letter-spacing: -1.25px; }
p { line-height: 1.85; }
[hidden] { display: none !important; }

assets/css/components.css.data:
.brand-mark {
  display: grid; place-items: center; width: 39px; height: 39px; border-radius: 13px;
  border: 1px solid rgba(160, 176, 255, .2); background: linear-gradient(145deg, #1d2b4c, #251c3e);
  color: #c6d2ff; font-size: 13px; font-weight: 850; letter-spacing: -1px;
}
.nav a { padding: 10px 10px; color: #a7b1c5; border: 1px solid transparent; border-radius: 10px; font-size: 11px; white-space: nowrap; transition: background .18s, color .18s, border-color .18s; }
.nav a:hover, .nav a[aria-current="location"] { color: var(--text); background: rgba(135, 161, 255, .08); border-color: rgba(135, 161, 255, .13); }
.menu-icon-close { display: none; }
.menu-toggle[aria-expanded="true"] .menu-icon-lines { display: none; }
.menu-toggle[aria-expanded="true"] .menu-icon-close { display: block; }
.header-cta { display: inline-flex; min-height: 41px; align-items: center; justify-content: center; gap: 9px; flex: 0 0 auto; padding: 0 14px; border: 1px solid rgba(143, 166, 255, .3); border-radius: 11px; background: rgba(123, 148, 255, .1); color: #dce4ff; font-size: 11px; font-weight: 700; white-space: nowrap; transition: border-color .18s, background .18s; }
.header-cta:hover { border-color: rgba(160, 179, 255, .62); background: rgba(123, 148, 255, .16); }
.eyebrow { display: inline-flex; align-items: center; flex-wrap: wrap; gap: 10px; margin-bottom: 23px; color: #aab8d7; font-size: 10px; font-weight: 780; letter-spacing: 1.7px; }
.eyebrow span { color: #65728d; }
h1 { max-width: 700px; margin: 0; font-size: clamp(43px, 6.6vw, 72px); line-height: 1.03; letter-spacing: -3.6px; font-weight: 770; }
h2 { margin: 0; font-size: clamp(28px, 3.6vw, 39px); line-height: 1.13; letter-spacing: -1.4px; font-weight: 730; }
h3 { margin: 0; font-size: 15px; letter-spacing: -.3px; line-height: 1.4; }
.gradient-text { color: #aec1ff; background: linear-gradient(105deg, #93b1ff 8%, #c2adff 100%); background-clip: text; -webkit-background-clip: text; }
.hero-description { max-width: 570px; margin: 21px 0 27px; color: #a1adc3; font-size: 14px; line-height: 1.9; }
.hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 9px; min-height: 45px; padding: 0 16px; border: 1px solid var(--border); border-radius: 11px; font-size: 12px; font-weight: 690; line-height: 1.3; text-align: center; transition: transform .16s, border-color .16s, background .16s; }
.button:hover { transform: translateY(-1px); border-color: rgba(160, 179, 255, .55); }
.button-primary { border-color: rgba(143, 166, 255, .35); background: linear-gradient(115deg, rgba(101, 133, 225, .25), rgba(149, 118, 216, .21)); color: #f1f4ff; }
.button-primary:hover { background: linear-gradient(115deg, rgba(101, 133, 225, .35), rgba(149, 118, 216, .3)); }
.button-secondary { background: rgba(255,255,255,.025); color: #c7d0e2; }
.button-small { min-height: 36px; padding: 0 12px; border-radius: 9px; font-size: 11px; }
.hero-footnote { display: flex; align-items: center; gap: 9px; margin-top: 24px; color: #8491aa; font-size: 11px; }
.hero-footnote-dot { width: 7px; height: 7px; border-radius: 50%; background: #8da8ff; box-shadow: 0 0 0 4px rgba(141,168,255,.09); }
.section-kicker { margin: 0 0 10px; color: #a5b5df; font-size: 10px; font-weight: 760; letter-spacing: 1.55px; text-transform: uppercase; }
.section-intro { max-width: 680px; margin: 13px 0 0; color: var(--muted); font-size: 13px; line-height: 1.85; }
.section-head-link, .text-link { display: inline-flex; align-items: center; gap: 8px; color: #bac8fa; font-size: 11px; font-weight: 680; white-space: nowrap; }
.section-head-link:hover, .text-link:hover { color: #fff; }
.hero-route-link { display: flex; align-items: center; gap: 12px; min-width: 0; padding: 12px 10px; border: 1px solid transparent; border-radius: 12px; transition: background .16s, border-color .16s; }
.hero-route-link:hover { border-color: rgba(145, 164, 220, .14); background: rgba(255,255,255,.035); }
.route-icon { display: grid; place-items: center; width: 34px; height: 34px; flex: 0 0 auto; border: 1px solid var(--border); border-radius: 10px; background: rgba(255,255,255,.025); color: #a9baff; font-size: 10px; font-weight: 760; }
.route-copy { display: grid; gap: 3px; min-width: 0; flex: 1; }
.route-copy strong { color: #e8edf9; font-size: 12px; font-weight: 680; }
.route-copy small { color: #8996ad; font-size: 10px; line-height: 1.55; }
.route-arrow { color: #9baad1; font-size: 14px; }
.hero-route-footer a { color: #96a3bd; font-size: 10px; font-weight: 650; }
.hero-route-footer a:hover { color: #eff2ff; }
.intro-fact-label { display: block; margin-bottom: 8px; color: #8895ad; font-size: 10px; font-weight: 680; letter-spacing: .9px; text-transform: uppercase; }
.intro-fact strong { display: block; color: #e4eaf8; font-size: 14px; font-weight: 720; letter-spacing: -.2px; }
.intro-fact p { margin: 6px 0 0; color: #8793a9; font-size: 11px; line-height: 1.7; }
.about-fact-card, .about-purpose-card, .about-bottom-card, .overview-card, .product-card, .project-row {
  position: relative; min-width: 0; padding: 22px; border: 1px solid var(--border); border-radius: var(--radius-card);
  background: linear-gradient(145deg, rgba(255,255,255,.028), rgba(255,255,255,.012));
}
.about-fact-card { min-height: 180px; }
.about-card-label { display: block; margin-bottom: 22px; color: #8794ad; font-size: 10px; font-weight: 700; letter-spacing: .75px; text-transform: uppercase; }
.about-fact-card h3 { font-size: 16px; color: #e5eaf7; }
.about-fact-card p, .about-purpose-card > p:not(.section-kicker), .about-bottom-card > p:not(.section-kicker) { margin: 10px 0 0; color: #9aa6bb; font-size: 12px; line-height: 1.8; }
.about-purpose-card { min-height: 205px; }
.about-purpose-card h3, .about-bottom-card h3 { font-size: 17px; letter-spacing: -.4px; }
.about-purpose-card .section-kicker, .about-bottom-card .section-kicker { margin-bottom: 13px; }
.about-vision-card { background: linear-gradient(140deg, rgba(105, 136, 219, .105), rgba(255,255,255,.015)); }
.about-values { color: #c5d0e7 !important; line-height: 2 !important; }
.about-muted { color: #7e8ba4 !important; font-size: 11px !important; }
.overview-card { padding: 22px; transition: border-color .18s, background .18s, transform .18s; }
.overview-card:hover { border-color: rgba(144, 163, 226, .23); }
.overview-card .card-index { display: block; margin-bottom: 20px; color: #7e91c4; font-size: 10px; font-weight: 760; letter-spacing: .7px; }
.card-copy { margin: 10px 0 0; color: #9aa6bb; font-size: 12px; line-height: 1.8; }
.mission-grid .overview-card { padding: 18px 20px; }
.mission-grid .overview-card h3 { font-size: 13px; }
.mission-grid .overview-card .card-copy { font-size: 11px; }
.product-card { display: flex; flex-direction: column; align-items: stretch; min-height: 295px; padding: 24px; }
.product-top { display: flex; align-items: center; gap: 13px; margin-bottom: 16px; }
.product-symbol { display: grid; place-items: center; width: 45px; height: 45px; flex: 0 0 auto; border: 1px solid rgba(151, 169, 234, .22); border-radius: 14px; background: linear-gradient(145deg, #1a2741, #231d39); color: #ced8ff; font-size: 13px; font-weight: 800; }
.product-identity { min-width: 0; }
.product-identity h3 { font-size: 16px; }
.product-label { display: block; margin-top: 4px; color: #8793aa; font-size: 10px; }
.product-description { display: -webkit-box; overflow: hidden; -webkit-line-clamp: 4; -webkit-box-orient: vertical; max-width: 620px; margin-top: 0; font-size: 12px; }
.product-card-footer { display: grid; gap: 15px; margin-top: auto; padding-top: 22px; }
.status-tag { display: inline-flex; align-items: center; justify-self: start; min-height: 26px; padding: 5px 9px; border: 1px solid rgba(153, 166, 195, .18); border-radius: 8px; background: rgba(255,255,255,.018); color: #aab5c9; font-size: 10px; font-weight: 650; }
.status-available { border-color: rgba(106, 188, 151, .24); color: #a8dfc6; background: rgba(106,188,151,.055); }
.status-development { border-color: rgba(225, 186, 113, .24); color: #e6cc9d; background: rgba(225,186,113,.045); }
.status-pending { border-color: rgba(168, 151, 239, .24); color: #c9bbf5; background: rgba(168,151,239,.045); }
.product-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 9px; }
.project-row { display: flex; align-items: center; gap: 13px; padding: 18px; }
.project-symbol { display: grid; place-items: center; width: 42px; height: 42px; flex: 0 0 auto; border: 1px solid var(--border); border-radius: 12px; background: rgba(255,255,255,.025); color: #b3c0e9; font-size: 11px; font-weight: 790; }
.project-copy { min-width: 0; flex: 1; }
.project-copy h3 { font-size: 13px; }
.project-copy p { margin: 5px 0 0; color: #8f9bb2; font-size: 11px; line-height: 1.65; }
.technology-grid .overview-card { min-height: 170px; }
.safety-grid .overview-card { min-height: 185px; }
.info-details { margin-top: 13px; padding-top: 12px; border-top: 1px solid var(--border); }
.info-details summary { color: #bbc8ed; cursor: pointer; font-size: 11px; font-weight: 650; }
.info-details summary:focus-visible { outline: 2px solid var(--blue); outline-offset: 4px; border-radius: 3px; }
.info-details p { margin: 10px 0 0; color: #9aa6bb; font-size: 11px; line-height: 1.8; }
.updates-empty-mark { display: grid; place-items: center; width: 42px; height: 42px; flex: 0 0 auto; border: 1px solid var(--border); border-radius: 13px; background: rgba(255,255,255,.025); color: #b4c3eb; font-size: 16px; font-weight: 740; }
.updates-empty h3 { font-size: 14px; }
.updates-empty p { max-width: 600px; margin: 7px 0 0; color: #909bb1; font-size: 11px; line-height: 1.8; }
.contact-method { display: flex; align-items: center; gap: 13px; min-width: 0; padding: 18px; border: 1px solid var(--border); border-radius: 14px; background: rgba(255,255,255,.018); transition: border-color .18s, background .18s, transform .18s; }
.contact-method:hover { border-color: rgba(143, 163, 225, .32); background: rgba(255,255,255,.035); transform: translateY(-1px); }
.contact-method-icon { display: grid; place-items: center; width: 38px; height: 38px; flex: 0 0 auto; border: 1px solid rgba(140, 160, 226, .17); border-radius: 11px; background: rgba(110, 137, 225, .075); color: #b9c8ff; font-size: 13px; font-weight: 760; }
.contact-method-copy { min-width: 0; flex: 1; display: grid; gap: 4px; }
.contact-method-copy strong { font-size: 12px; font-weight: 690; }
.contact-method-copy small { overflow-wrap: anywhere; color: #929eb5; font-size: 10px; line-height: 1.6; }
.contact-method-arrow { color: #a0aed1; font-size: 14px; }
.contact-bottom > span { color: #9ba7bd; font-size: 11px; }
.footer-brand > p { margin: 15px 0 0; color: #8793a9; font-size: 11px; line-height: 1.8; }
.footer-group { display: grid; align-content: start; justify-items: start; gap: 11px; }
.footer-group strong { margin-bottom: 3px; color: #e0e6f4; font-size: 11px; }
.footer-group a { color: #929eb4; font-size: 11px; }
.footer-group a:hover { color: #edf1fa; }
.footer-bottom { color: #7f8ba3; font-size: 10px; line-height: 1.7; }


/* Editorial motion: restrained movement, never blocks content. */
.motion-reveal {
  opacity: 0;
  transform: translate3d(0, 18px, 0);
  transition:
    opacity 720ms cubic-bezier(.2,.7,.2,1) var(--reveal-delay, 0ms),
    transform 720ms cubic-bezier(.2,.7,.2,1) var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}
.motion-reveal.is-visible {
  opacity: 1;
  transform: translate3d(0, 0, 0);
}
.hero-content, .hero-route-panel {
  animation: tcs-hero-enter 900ms cubic-bezier(.2,.7,.2,1) both;
}
.hero-route-panel { animation-delay: 110ms; }
.founder-profile-link { margin-top: 12px; }
@keyframes tcs-hero-enter {
  from { opacity: 0; transform: translate3d(0, 20px, 0); }
  to { opacity: 1; transform: translate3d(0, 0, 0); }
}
@media (prefers-reduced-motion: reduce) {
  .motion-reveal, .hero-content, .hero-route-panel {
    opacity: 1 !important;
    transform: none !important;
    animation: none !important;
    transition: none !important;
    will-change: auto;
  }
}

