assets/css/diagnostics.css.data:
.diagnostic-panel {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 1000;
  display: block;
  width: min(680px, calc(100vw - 40px));
  max-height: min(76vh, 760px);
  overflow: auto;
  padding: 18px;
  border: 1px solid rgba(255, 145, 118, .45);
  border-radius: 16px;
  background: #11131d;
  color: #f4f5fb;
  box-shadow: 0 22px 70px rgba(0, 0, 0, .5);
  font-size: 12px;
  line-height: 1.6;
}
.diagnostic-panel[hidden] { display: none; }
.diagnostic-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.diagnostic-actions {
  display: flex;
  flex-wrap: wrap;
  flex: 0 0 auto;
  gap: 7px;
}
.diagnostic-copy,
.diagnostic-close {
  min-height: 34px;
  padding: 0 11px;
  border: 1px solid rgba(255, 255, 255, .16);
  border-radius: 9px;
  background: rgba(255, 255, 255, .06);
  color: #f4f5fb;
  cursor: pointer;
}
.diagnostic-copy { border-color: rgba(255, 181, 160, .4); }
.diagnostic-copy:hover,
.diagnostic-close:hover { background: rgba(255, 255, 255, .12); }
.diagnostic-copy-status {
  margin: 0 0 10px;
  color: #bdc7df;
  font-size: 11px;
}
.diagnostic-kicker {
  margin: 0 0 4px;
  color: #ffb5a0;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}
.diagnostic-panel h2 {
  margin: 0;
  color: #fff;
  font-size: 20px;
  letter-spacing: -.4px;
  line-height: 1.25;
}
.diagnostic-summary {
  margin: 8px 0 12px;
  color: #b4bbcf;
}

.diagnostic-list {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.diagnostic-item {
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, .1);
  border-radius: 10px;
  background: rgba(255, 255, 255, .025);
}
.diagnostic-item > details { padding: 10px 12px; }
.diagnostic-item summary {
  color: #ffe2da;
  cursor: pointer;
  font-weight: 700;
  overflow-wrap: anywhere;
}
.diagnostic-fields {
  display: grid;
  gap: 8px;
  margin: 12px 0 0;
}
.diagnostic-field {
  display: grid;
  grid-template-columns: minmax(110px, .32fr) minmax(0, 1fr);
  gap: 12px;
  padding-top: 7px;
  border-top: 1px solid rgba(255, 255, 255, .07);
}
.diagnostic-field dt { color: #9da8c2; }
.diagnostic-field dd {
  min-width: 0;
  margin: 0;
  color: #f1f3fb;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}
.diagnostic-stack {
  max-height: 180px;
  overflow: auto;
  margin: 10px 0 0;
  padding: 10px;
  border-radius: 8px;
  background: #090b11;
  color: #cbd2e6;
  font: 11px/1.5 ui-monospace, SFMono-Regular, Consolas, monospace;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

assets/css/layout.css.data:
.site-shell { min-height: 100vh; }
.container { width: min(var(--content), calc(100% - 56px)); margin: 0 auto; }
.topbar {
  position: sticky; top: 0; z-index: 20; min-height: 74px; display: flex; align-items: center;
  border-bottom: 1px solid var(--border); background: rgba(11, 15, 23, .93); backdrop-filter: blur(18px);
}
.topbar-inner { width: min(var(--content), calc(100% - 56px)); min-height: 74px; margin: auto; display: flex; align-items: center; gap: 25px; }
.brand { display: inline-flex; align-items: center; gap: 11px; flex: 0 0 auto; }
.brand-copy { display: flex; flex-direction: column; gap: 3px; }
.brand-name { font-size: 13px; font-weight: 760; letter-spacing: -.25px; }
.brand-sub { color: var(--muted); font-size: 10px; }
.nav { display: flex; align-items: center; justify-content: flex-end; gap: 3px; margin-left: auto; }
.menu-toggle { display: none; width: 41px; height: 41px; border: 1px solid var(--border); border-radius: 12px; background: rgba(255,255,255,.025); cursor: pointer; }
.hero {
  position: relative;
  padding: clamp(48px, 7vw, 82px) 0 clamp(42px, 6vw, 70px);
  border-bottom: 1px solid var(--border);
  background: radial-gradient(ellipse at 8% 0%, rgba(75, 105, 185, .13), transparent 38rem);
}
.hero-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(330px, .72fr); align-items: center; gap: clamp(32px, 5vw, 68px); }
.hero-content { max-width: 650px; }
.hero-route-panel {
  min-width: 0; padding: 22px; border: 1px solid var(--border); border-radius: 22px;
  background: linear-gradient(145deg, rgba(20, 28, 43, .94), rgba(16, 22, 33, .88));
  box-shadow: 0 22px 60px rgba(0,0,0,.14);
}
.hero-route-heading { display: flex; align-items: end; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.hero-route-heading .section-kicker { margin-bottom: 7px; }
.hero-route-heading h2 { font-size: 20px; letter-spacing: -.65px; }
.hero-route-list { display: grid; gap: 5px; }
.hero-route-footer { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 14px; padding: 13px 2px 0; border-top: 1px solid var(--border); }
.intro-strip { border-bottom: 1px solid var(--border); background: rgba(255,255,255,.012); }
.intro-strip-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); }
.intro-fact { min-width: 0; padding: 24px 25px; border-right: 1px solid var(--border); }
.intro-fact:first-child { padding-left: 0; }
.intro-fact:last-child { border-right: 0; padding-right: 0; }
.section { padding: clamp(54px, 6.5vw, 78px) 0; border-bottom: 1px solid var(--border); scroll-margin-top: 82px; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 28px; margin-bottom: 28px; }
.section-head-row { align-items: end; }
.section-head-link { flex: 0 0 auto; }
.section-subhead { display: flex; justify-content: space-between; align-items: end; margin: 35px 0 17px; }
.about-facts-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.about-purpose-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 14px; }
.mission-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.about-bottom-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-top: 28px; }
.product-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: stretch; }
.projects-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; align-items: stretch; }
.technology-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.safety-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; align-items: stretch; }
.updates-empty { display: flex; align-items: center; gap: 18px; padding: 24px; border: 1px solid var(--border); border-radius: 17px; background: rgba(255,255,255,.018); }
